"""The project's name, in exactly one place.

Everything the program SAYS about itself -- the CLI's prog name, the
"# generated by" stamp on every output, the error-code prefix,
environment-variable names -- is derived from the constants below.

The name also exists in places Python cannot derive at runtime: the package
directory (``src/evidome/``), ``pyproject.toml``'s distribution name and
console script, and ``import evidome`` lines in the tests.
``tests/test_the_name_lives_in_one_place.py`` fails if the name leaks into any
other source file -- a hard-coded copy of the name somewhere else is exactly
the "one contract, two implementations" defect that drifts silently.

Inside ``src/`` every import is RELATIVE for the same reason: a package that
imports itself by name has as many copies of its name as it has modules.
"""

from __future__ import annotations

#: Import-package / distribution / console-script name. Lower case, no spaces.
NAME = "evidome"

#: How the program refers to itself in prose (report headers, --version).
DISPLAY_NAME = "Evidome"

#: Prefix for environment variables the program reads (e.g. EVIDOME_HOME).
ENV_PREFIX = NAME.upper()

#: Prefix for numbered error codes (e.g. EVD-0001).
ERROR_PREFIX = "EVD"


def env_var(suffix: str) -> str:
    """``env_var("HOME")`` -> ``"EVIDOME_HOME"``."""
    return f"{ENV_PREFIX}_{suffix}"
